+                name="email" 
+                type="email" 
+                autoComplete="email"
+                required
+                aria-invalid={!!errors.email}
+                aria-describedby={errors.email ? "email-error" : undefined}
+                value={formData.email}
+                onChange={handleChange}
+                onBlur={handleBlur}
+              />
+              {errors.email && <p id="email-error" className="error-message">{errors.email}</p>}
